            <tr key={`${r.grade}-${r.from}`} data-testid={`rate-row-${r.grade}-${r.from || 'start'}`}>
              <td>{r.grade}</td>
              <td data-testid="rate-from">{r.from || 'start'}</td>
              <td data-testid="rate-to">{r.to}</td>
              <td data-testid="rate-pct">{r.rate}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form
        data-testid="rate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync({ grade, rate: pct.trim(), from: from.trim(), to: to.trim() });
          });
        }}
      >
        <select
          data-testid="rate-form-grade"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            save.reset();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>{g}</option>
          ))}
        </select>{' '}
        <input
          data-testid="rate-form-pct"
          value={pct}
          placeholder="Rate %"
          onChange={(e) => {
            setPct(e.target.value);
            save.reset();
          }}
        />{' '}
        <input
          data-testid="rate-form-from"
          value={from}
          placeholder="From (YYYY-MM-DD, blank: always)"
          onChange={(e) => {
            setFrom(e.target.value);
            save.reset();
          }}
        />{' '}
        <input
          data-testid="rate-form-to"
          value={to}
          placeholder="To (YYYY-MM-DD, blank: no end)"
          onChange={(e) => {
            setTo(e.target.value);
            save.reset();
          }}
        />{' '}
        <button type="submit" data-testid="rate-form-submit">Set rate</button>
        {save.isError && <span data-testid="rate-form-error" role="alert"> Could not set the rate: it must be a percent of 0.00 or more with at most two decimals, from a valid date (YYYY-MM-DD) or none, to a valid date not before it or none.</span>}
      </form>
      <ImportRates />
      <RatePreview />
    </>
  );
}
import { useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { readPath, useAsOf } from '../asof/useAsOf';

/** A grade's rate: a percent shown with two decimals ("12.50"), in force from a date (YYYY-MM-DD;
 *  "" for from the beginning of time) through a date ("" for no end). One inherited from an ancestor
 *  sheet has its level: 1 the parent, 2 the parent's parent, 3 the one above; the sheet's own have none. */
export type Rate = { grade: string; rate: string; from: string; to: string; level?: number };

export const ratesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'rates', asOf] as const;

export const inheritedRatesKey = (sheet: string, asOf = '') => ['sheet', sheet, 'inherited-rates', asOf] as const;

/** The sheet's own rates, by grade then from-date (from the beginning of time first), followed by
 *  its ancestors' (nearest first), each with its level. */
export function useRates(sheet: string): Rate[] {
  const asOf = useAsOf();
  const { data } = useQuery({
    queryKey: ratesKey(sheet, asOf),
    queryFn: () => getJson<Rate[]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/rates`, asOf)),
    enabled: sheet !== '',
  });
  const { data: inherited } = useQuery({
    queryKey: inheritedRatesKey(sheet, asOf),
    queryFn: () => getJson<Rate[][]>(readPath(`/api/sheets/${encodeURIComponent(sheet)}/inherited-rates`, asOf)),
    enabled: sheet !== '',
  });
  return useMemo(
    () => [...(data ?? []), ...(inherited ?? []).flatMap((rates, i) => rates.map((r) => ({ ...r, level: i + 1 })))],
    [data, inherited],
  );
}

/** One sheet's grade rate in force on a date: the one with the latest from-date on or before it;
 *  undefined when none applies, or when that one's to-date is before the date. */
function ownRateOn(rates: Rate[], grade: string, date: string, level: number): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if ((r.level ?? 0) === level && r.grade === grade && r.from <= date && (found === undefined || r.from >= found.from)) found = r;
  }
  if (found === undefined || (found.to !== '' && found.to < date)) return undefined;
  return found.rate;
}

/** The grade's rate in force on a date: the sheet's own (see ownRateOn); when it has none, its parent's,
 *  then the parent's parent's, up to three levels up; undefined when none has one (or the date is not known yet). */
export function rateOn(rates: Rate[], grade: string, date: string | undefined): string | undefined {
  if (date === undefined) return undefined;
  for (let level = 0; level <= 3; level++) {
    const found = ownRateOn(rates, grade, date, level);
    if (found !== undefined) return found;
  }
  return undefined;
}

